(()=>{'use strict';async function update(){let enabled=false;try{const config=await fetch('family-access-config.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()});if(!config.enabled)return;enabled=true;const response=await fetch(config.supabaseUrl+'/rest/v1/rpc/family_snapshot',{method:'POST',headers:{apikey:config.publishableKey,'Content-Type':'application/json'},body:'{}',cache:'no-store',signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error();const data=await response.json();if(data.schema_version!==1||!data.trees?.length||!Array.isArray(data.profiles))throw Error();document.getElementById('genealogy-data').textContent=JSON.stringify(data.trees);document.getElementById('family-portraits-data').textContent=JSON.stringify(data.profiles);window.dispatchEvent(new CustomEvent('family-genealogy-updated',{detail:data}));}catch{if(enabled){const note=document.createElement('p');note.className='detail-note';note.setAttribute('role','status');note.textContent='Ultimi aggiornamenti non disponibili. È visibile la copia conservata nell’archivio.';document.querySelector('.page-heading')?.append(note);}}}update();})();
